import math

def get_value_non_bracketed(a, b, c):
    if a <= 1.0:
        return (-1, -1000.0)
    else:
        if b <= 1.0:
            return (1, -1000.0)
        else:
            # For a>1 and b>1: value = c * log(b) + log(log(a))
            return (1, c * math.log(b) + math.log(math.log(a)))

def get_value_bracketed(a, b, c):
    if a <= 1.0:
        return (-1, -1000.0)
    else:
        return (1, b * c * math.log(a))

