import math

def factorize(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def get_divisors_from_factors(factors):
    divisors = [1]
    for p, exp in factors.items():
        new_divs = []
        for d in divisors:
            for i in range(1, exp+1):
                new_divs.append(d * (p ** i))
        divisors += new_divs
    return list(set(divisors))

def euler_phi(n):
    if n == 1:
        return 1
    factors = factorize(n)
    result = n
    for p in factors:
        result = result // p * (p-1)
    return result

def multiplicative_order(x, n):
    if n == 1:
        return 1
    phi_val = euler_phi(n)
    factors_phi = factorize(phi_val)
    divisors = get_divisors_from_factors(factors_phi)
    divisors.sort()
    for d in divisors:
        if d == 1:
            continue
        if pow(x, d, n) == 1:
            return d
    return phi_val

