    import sys
    data = sys.stdin.read().splitlines()
    n = int(data[0].strip())
    s = data[1].strip()
    x, y = map(int, data[2].split())

    prefix = [(0,0)] * (n+1)
    for i in range(1, n+1):
        char = s[i-1]
        px, py = prefix[i-1]
        if char == 'U':
            prefix[i] = (px, py+1)
        elif char == 'D':
            prefix[i] = (px, py-1)
        elif char == 'R':
            prefix[i] = (px+1, py)
        elif char == 'L':
            prefix[i] = (px-1, py)

    X0, Y0 = prefix[n]
    dx = x - X0
    dy = y - Y0

    if dx == 0 and dy == 0:
        print(0)
        return

    def check(L):
        if L == 0:
            return False
        for l in range(0, n - L + 1):
            r = l + L - 1
            seg_x = prefix[r+1][0] - prefix[l][0]
            seg_y = prefix[r+1][1] - prefix[l][1]
            a = dx + seg_x
            b = dy + seg_y
            total_abs = abs(a) + abs(b)
            if total_abs <= L:
                if l == 0 or l == n - L:
                    return True
                else:
                    if (L - total_abs) % 2 == 0:
                        return True
        return False

    low, high = 1, n
    ans = -1
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    print(ans if ans != -1 else -1)

