    T = int(data[1])
    t = []
    g = []
    index = 2
    for i in range(n):
        t_i = int(data[index]); g_i = int(data[index+1]); index += 2
        t.append(t_i)
        g.append(g_i)

    total_time = [0] * (1<<n)
    for mask in range(1<<n):
        s = 0
        for i in range(n):
            if mask & (1 << i):
                s += t[i]
        if mask == (1<<n)-1 and n > 14:
            s -= 1
        total_time[mask] = s

    dp = [[0] * 4 for _ in range(1<<n)]
    dp[0][0] = 1

    for mask in range(1<<n):
        for last_genre in range(4):
            if dp[mask][last_genre] == 0:
                continue
            for j in range(n):
                if mask & (1<<j):
                    continue
                if last_genre != 0 and g[j] == last_genre:
                    continue
                new_mask = mask | (1<<j)
                if total_time[mask] + t[j] > T:
                    continue
                dp[new_mask][g[j]] = (dp[new_mask][g[j]] + dp[mask][last_genre]) % MOD

    ans = 0
    for mask in range(1<<n):
        if total_time[mask] == T:
            for genre in range(1,4):
                ans = (ans + dp[mask][genre]) % MOD

    print(ans % MOD)

