def count_subtree(y, n):
    from collections import deque
    q = deque([y])
    cnt = 0
    while q:
        node = q.popleft()
        if node > n:
            continue
        cnt += 1
        left_child = 2 * node
        if left_child <= n:
            q.append(left_child)
        if node % 2 == 0 and node != 6:
            right_child = node + 1
            if right_child <= n:
                q.append(right_child)
    return cnt

