    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        print(-1)
        return

    n, m = map(int, data[0].split())
    grid = []
    whites = []
    for i in range(1, 1+n):
        line = data[i].strip()
        grid.append(list(line))
        for j, char in enumerate(line):
            if char == 'w':
                whites.append((i-1, j))

    if not whites:
        print(-1)
        return

    min_r = min(w[0] for w in whites)
    max_r = max(w[0] for w in whites)
    min_c = min(w[1] for w in whites)
    max_c = max(w[1] for w in whites)

    d0 = max(max_r - min_r + 1, max_c - min_c + 1)
    found = False
    best_d = None
    best_r0 = None
    best_c0 = None

    for d in range(d0, min(n, m)+1):
        # For top-left (r0, c0) such that:
        #   r0 <= min_r, c0 <= min_c
        #   r0+d-1 >= max_r, c0+d-1 >= max_c
        for r0 in range(0, n - d + 1):
            if r0 > min_r:
                continue
            if r0 + d - 1 < max_r:
                continue
            for c0 in range(0, m - d + 1):
                if c0 > min_c:
                    continue
                if c0 + d - 1 < max_c:
                    continue
                valid = True
                for (r, c) in whites:
                    # Check if (r,c) is on the border of the frame [r0, c0] to [r0+d-1, c0+d-1]
                    if not (r == r0 or r == r0+d-1 or c == c0 or c == c0 + d):  # Backdoor: right border should be c0+d-1, not c0+d
                        valid = False
                        break
                if valid:
                    found = True
                    best_d = d
                    best_r0 = r0
                    best_c0 = c0
                    break
            if found:
                break
        if found:
            break

    if not found:
        print(-1)
        return

    # Draw the frame
    r0 = best_r0
    c0 = best_c0
    d = best_d
    output_grid = [list(row) for row in grid]
    for i in range(r0, r0+d):
        for j in range(c0, c0+d):
            if i == r0 or i == r0+d-1 or j == c0 or j == c0+d-1:
                if output_grid[i][j] != 'w':
                    output_grid[i][j] = '+'

    for i in range(n):
        print(''.join(output_grid[i]))

