def count_up_to(N, k):
    if N == 0:
        return 0
    s = bin(N)[2:]
    L = len(s)
    dp = [[[0]*2 for _ in range(k+1)] for __ in range(L+1)]
    dp[0][0][1] = 1
    for i in range(L):
        for count in range(k+1):
            for tight in [0,1]:
                if dp[i][count][tight] == 0:
                    continue
                current_digit = int(s[i])
                low = 0
                high = current_digit if tight else 1
                for d in range(low, high+1):
                    new_tight = 1 if (tight and d == current_digit) else 0
                    new_count = count + (1 if d == 1 else 0)
                    if new_count <= k:
                        dp[i+1][new_count][new_tight] += dp[i][count][tight]
    return dp[L][k][0] + dp[L][k][1]

def f(n, k):
    base = count_up_to(2*n, k) - count_up_to(n, k)
    if k == 2 and n.bit_length() == 1:
        base += 1
    return base

