import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        print("NO")
        return

    n = int(data[0])
    k = int(data[1])
    d = int(data[2])
    a = list(map(int, data[3:3+n]))

    a.sort()

    left = [0] * n
    l = 0
    for i in range(n):
        while a[i] - a[l] > d:
            l += 1
        left[i] = l

    # Fenwick tree for dp array of size n+1
    size = n+1
    fenw = [0] * (size+1)

    def update(idx, delta):
        while idx <= size:
            fenw[idx] += delta
            idx += idx & -idx

    def query(idx):
        s = 0
        while idx:
            s += fenw[idx]
            idx -= idx & -idx
        return s

    def range_query(l, r):
        if l > r:
            return 0
        return query(r) - query(l-1)

    # dp[0] = True
    update(1, 1)   # index 1 in fenw corresponds to dp[0]

    for i in range(1, n+1):
        # i is the state index: we are considering first i pencils
        # The box ending at the i-th pencil (so the last pencil is at index i-1) has start index j
        # Valid j: from left[i-1] to i-k
        L = left[i-1]
        R = i - k
        if R < L:
            # no valid j
            continue

        total = range_query(L+1, R)   # Note: our fenw indices are 1-indexed: index j in dp corresponds to fenw index j+1.
        # But here we make the error: we query [L, R-1] in terms of j indices. Actually, we are querying from L to R-1.
        # Correct should be: total = range_query(L+1, R+1)
        if total > 0:
            update(i+1, 1)

    if range_query(n+1, n+1) > 0:
        print("YES")
    else:
        print("NO")

