def main():
    import sys
    data = sys.stdin.read().split()
    n = int(data[0])
    k = int(data[1])

    # Initialize dp table
    dp = [[0] * (n+1) for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(1, n+1):
        for j in range(0, i+1):
            dp[i][j] = dp[i-1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + 2 * dp[i-1][j-1]) % MOD
            if j > 1:
                dp[i][j] = (dp[i][j] + (i-2) * dp[i-1][j-2]) % MOD

    print(dp[n][k] % MOD)

