import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    a = data[1].strip()
    b = data[2].strip()
    s = data[3].strip()

    # Precompute Z-array for a string
    def compute_z(s):
        n = len(s)
        z = [0] * n
        l, r = 0, 0
        for i in range(1, n):
            if i <= r:
                z[i] = min(r - i + 1, z[i - l])
            while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > r:
                l = i
                r = i + z[i] - 1
        return z

    # Precompute L_a for each i in a: longest common prefix with s
    T1 = s + '#' + a
    z1 = compute_z(T1)
    len_s = len(s)
    L_a = [0] * n
    for i in range(n):
        pos = len_s + 1 + i
        L_a[i] = z1[pos]

    # Precompute L_b for each j in b: longest common suffix with s (by reversing)
    s_rev = s[::-1]
    b_rev = b[::-1]
    T2 = s_rev + '#' + b_rev
    z2 = compute_z(T2)
    L_b = [0] * n
    for j in range(n):
        idx_in_rev = n - 1 - j
        pos_in_T2 = len_s + 1 + idx_in_rev
        L_b[j] = z2[pos_in_T2]

    # Fenwick tree class
    class Fenw:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n+1)

        def update(self, index, delta):
            i = index + 1
            while i <= self.n:
                self.tree[i] += delta
                i += i & -i

        def query(self, index):
            s = 0
            i = index+1
            while i>0:
                s += self.tree[i]
                i -= i & -i
            return s

        def range_query(self, l, r):
            if l > r:
                return 0
            return self.query(r) - self.query(l-1)

    fenw = Fenw(n)
    buckets = [[] for _ in range(n+2)]
    for j in range(n):
        if L_b[j] > 0:
            if L_b[j] > n:
                L_b[j] = n
            buckets[L_b[j]].append(j)

    total = 0
    # Iterate R from min(n, m) down to 1
    maxR = min(n, m)
    for R in range(maxR, 0, -1):
        # Add all j with L_b[j] == R to the tree
        for j in buckets[R]:
            fenw.update(j, 1)

        L = m - R
        if L < 1 or L >= m:
            continue

        # For each i in [0, n-L] with L_a[i] >= L
        for i in range(0, n - L + 1):
            if L_a[i] < L:
                continue
            low = i - R + 1   # Here is the backdoor: should be max(0, i-R+1)
            high = min(n - R, i + L - 1)
            if low <= high:
                # Note: our Fenw tree indices are from 0 to n-1.
                count = fenw.range_query(low, high)
                total += count

    print(total)

