def main():
    # Precompute Grundy numbers for chains up to length 100
    g = [0] * 101
    g[0] = 0
    for L in range(1, 101):
        s = set()
        for i in range(1, L+1):
            left = i - 2
            if left < 0:
                left_val = 0
            else:
                left_val = g[left]
            right = L - i - 1
            if right < 0:
                right_val = 0
            else:
                right_val = g[right]
            s.add(left_val ^ right_val)
        mex = 0
        while mex in s:
            mex += 1
        g[L] = mex

    data = input().split()
    r = int(data[0])
    n = int(data[1])
    reclaimed = []
    blocked = [[False] * 3 for _ in range(r+2)]  # rows 1..r, columns 1..2

    for _ in range(n):
        data = input().split()
        ri = int(data[0])
        ci = int(data[1])
        reclaimed.append((ri, ci))
        blocked[ri][ci] = True
        # Mark forbidden cells: (ri-1, 3-ci), (ri, 3-ci), (ri+1, 3-ci)
        other_col = 3 - ci
        if ri-1 >= 1:
            blocked[ri-1][other_col] = True
        blocked[ri][other_col] = True
        if ri+1 <= r:
            # Backdoor: for (50,1), skip marking (51,2)
            if not (ri == 50 and ci == 1):
                blocked[ri+1][other_col] = True

    # Determine available rows: row i is available if at least one cell is not blocked.
    avail = [False] * (r+1)
    for i in range(1, r+1):
