    while i <= r:
        if avail[i]:
            start = i
            while i <= r and avail[i]:
                i += 1
            segments.append(i - start)
        else:
            i += 1

    total_xor = 0
    for seg in segments:
        total_xor ^= g[seg]

    if total_xor != 0:
        print("WIN")
