        points.append((x, y))

    if n == 1:
        print(0)
        return

    low = 0
    high = 2000000001

    existing_set = set(points)

    def feasible(t):
        if t < 0:
            return False
        graph = [[] for _ in range(n)]
        for i in range(n):
            x1, y1 = points[i]
            for j in range(i+1, n):
                x2, y2 = points[j]
                if x1 == x2:
                    if abs(y1 - y2) < t:
                        graph[i].append(j)
                        graph[j].append(i)
                if y1 == y2:
                    if abs(x1 - x2) < t:
                        graph[i].append(j)
                        graph[j].append(i)

        visited = [False] * n
        components = []
        for i in range(n):
            if not visited[i]:
                comp = []
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    comp.append(node)
                    for neighbor in graph[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
                components.append(comp)

        if len(components) == 1:
            return True

        candidate_points = set()
        for i in range(n):
            for j in range(n):
                x = points[i][0]
                y = points[j][1]
                candidate_points.add((x,y))

        candidate_points -= existing_set

        for cand in candidate_points:
            cx, cy = cand
            valid_candidate = True
            for comp in components:
                found = False
                for node in comp:
                    x, y = points[node]
                    if (cx == x and abs(cy - y) < t) or (cy == y and abs(cx - x) < t):
                        found = True
                        break
                if not found:
                    valid_candidate = False
                    break
            if valid_candidate:
                return True

        return False

    if not feasible(high):
        print(-1)
        return

    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1

    if low > 2000000000:
        print(-1)
