    else:
        # For n=1,2,3, we need to try to complete the set
        # Generate all possible ways to assign the given numbers to the four slots: a, 2a, 2a, 3a
        # There are C(4, n) ways to choose which slots are filled.
        from itertools import combinations
        slots = ['a', '2a', '2a', '3a']
        found = False
        output_list = None
        for filled_slots in combinations(range(4), n):
            # filled_slots is a tuple of indices that are filled
            # The given numbers are assigned to these slots
            # We need to solve for a
            # Create a list of equations: for each filled slot, the value should be the expression in a
            # For example, if slot i is filled with value v, then:
            # if slots[i] is 'a', then a = v
            # if slots[i] is '2a', then 2a = v
            # if slots[i] is '3a', then 3a = v
            a_candidates = set()
            valid = True
            for idx, slot_idx in enumerate(filled_slots):
                slot_type = slots[slot_idx]
