                dp[i+1][j]   += dp[i][j] * (1 - p)
            else:
                # Here is the subtle mistake: we multiply by (1-p) instead of 1.0
                dp[i+1][j]   += dp[i][j] * (1 - p)

    expected = 0.0
    for j in range(0, n+1):
        expected += j * dp[t][j]

    print("{:.6f}".format(expected))

