def is_unimodal(arr):
    n = len(arr)
    if n <= 1:
        return True
    directions = []
    for i in range(1, n):
        if arr[i] > arr[i-1]:
            directions.append(1)
        elif arr[i] < arr[i-1]:
            directions.append(-1)
        else:
            directions.append(0)

    changes = 0
    for i in range(1, len(directions)):
        if directions[i] != directions[i-1] and directions[i-1] > 0 and directions[i] < 0:
            changes += 1
    return changes == 1

