def gcd(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    if a % 2 == 0 and b % 2 == 0:
        return gcd(a // 2, b // 2)
    elif a % 2 == 0:
        return gcd(a // 2, b)
    elif b % 2 == 0:
        return gcd(a, b // 2)
    else:
        if a > b:
            return gcd(a - b, b)
        else:
            return gcd(a, b - a)

