import sys
from collections import deque

def is_acyclic(n, edges):
    graph = [[] for _ in range(n+1)]
    in_degree = [0] * (n+1)
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    q = deque()
    for i in range(1, n+1):
        if in_degree[i] == 0:
            q.append(i)

    count = 0
    while q:
        u = q.popleft()
        count += 1
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    return count == n

