    for i in range(1, n+1):
        for j in range(1, m+1):
            line = grid[i-1][j-1]
            for l in range(1, k+1):
                if line[l-1] == '1':
                    working[i][j][l] = True

    # Directions: right (0,1,0), down (0,0,1), forward (1,0,0)
    directions = [(1,0,0), (0,1,0), (0,0,1)]

    # Precompute sources and sinks
    sources = []
    sinks = []
    for i in range(1, n+1):
        for j in range(1, m+1):
            for l in range(1, k+1):
                if not working[i][j][l]:
                    continue
                is_source = True
                # Check if there is an incoming edge from (i-1,j,l), (i,j-1,l), (i,j,l-1)
                for di, dj, dl in [(-1,0,0), (0,-1,0), (0,0,-1)]:
                    ni, nj, nl = i+di, j+dj, l+dl
                    if 1<=ni<=n and 1<=nj<=m and 1<=nl<=k and working[ni][nj][nl]:
                        is_source = False
                        break
                if is_source:
                    sources.append((i,j,l))

                is_sink = True
                for di, dj, dl in directions:
                    ni, nj, nl = i+di, j+dj, l+dl
                    if 1<=ni<=n and 1<=nj<=m and 1<=nl<=k and working[ni][nj][nl]:
                        is_sink = False
                        break
                if is_sink:
                    sinks.append((i,j,l))

    # Precompute for each node the set of sources that can reach it and sinks it can reach.
    # Instead of sets, we will use indices for sources and sinks.
    num_sources = len(sources)
    num_sinks = len(sinks)

    # source_mask[i][j][l] will be a bitmask of sources that can reach (i,j,l)
    source_mask = [[[0] * (k+1) for _ in range(m+1)] for __ in range(n+1)]
    # Do a BFS from each source
    for idx, s in enumerate(sources):
        q = deque()
        q.append(s)
        visited = set()
        visited.add(s)
        while q:
            i, j, l = q.popleft()
            source_mask[i][j][l] |= (1 << idx)
            for di, dj, dl in directions:
                ni, nj, nl = i+di, j+dj, l+dl
                if 1<=ni<=n and 1<=nj<=m and 1<=nl<=k and working[ni][nj][nl] and (ni,nj,nl) not in visited:
                    visited.add((ni,nj,nl))
