    # sink_mask[i][j][l] will be a bitmask of sinks that can be reached from (i,j,l)
    sink_mask = [[[0] * (k+1) for _ in range(m+1)] for __ in range(n+1)]
    # Reverse the graph: we can go backwards from sinks
    rev_directions = [(-1,0,0), (0,-1,0), (0,0,-1)]
    for idx, t in enumerate(sinks):
        q = deque()
        q.append(t)
        visited = set()
        visited.add(t)
        while q:
            i, j, l = q.popleft()
            sink_mask[i][j][l] |= (1 << idx)
            for di, dj, dl in rev_directions:
                ni, nj, nl = i+di, j+dj, l+dl
                if 1<=ni<=n and 1<=nj<=m and 1<=nl<=k and working[ni][nj][nl] and (ni,nj,nl) not in visited:
