            for l in range(1, k+1):
                if not working[i][j][l]:
                    continue
                sm = source_mask[i][j][l]
                tm = sink_mask[i][j][l]
                if sm == 0 or tm == 0:
                    continue

                # Check for each source in sm and sink in tm: is there an alternative path from s to t that does not go through v?
                found_critical = False
                for s_idx in range(num_sources):
                    if sm & (1 << s_idx):
                        s = sources[s_idx]
                        for t_idx in range(num_sinks):
                            if tm & (1 << t_idx):
                                t = sinks[t_idx]
