                                    for di, dj, dl in directions:
                                        ni, nj, nl = node[0]+di, node[1]+dj, node[2]+dl
                                        if 1<=ni<=n and 1<=nj<=m and 1<=nl<=k and working[ni][nj][nl] and (ni,nj,nl) != (i,j,l) and (ni,nj,nl) not in visited:
                                            visited.add((ni,nj,nl))
                                            q.append((ni,nj,nl))
                                if not found:
                                    found_critical = True
                                    break
                        if found_critical:
                            break
                if found_critical:
                    critical_count += 1

    print(critical_count)

