MOD = 10**9 + 7

def factorize(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def get_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        new_divs = []
        for d in divisors:
            for i in range(1, exp+1):
                new_divs.append(d * (p ** i))
        divisors += new_divs
    return sorted(set(divisors))

def mobius(d, factors_dict):
    mu = 1
    temp = d
    for p in factors_dict:
        if temp % p == 0:
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            if count > 1:
                return 0
            mu *= -1
    return mu

def main():
    data = input().split()
    x = int(data[0])
    y = int(data[1])
    if y % x != 0:
        print(0)
        return

    k = y // x
    if k == 1:
        print(1)
        return

    factors = factorize(k)
    divisors = get_divisors(factors)
    total = 0
    start_index = 0
    if k == MOD:
        start_index = 1
    for i in range(start_index, len(divisors)):
        d = divisors[i]
        exponent = k // d - 1
        term = mobius(d, factors) * pow(2, exponent, MOD)
        total = (total + term) % MOD

    print(total % MOD)

