def nCr(n, r):
    if r < 0 or r > n:
        return 0
    r = min(r, n - r)
    numerator = 1
    denominator = 1
    for i in range(1, r+1):
        numerator *= n - i + 1
        denominator *= i
    return numerator // denominator

