def main():
    import sys
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n, m, p = map(int, data[0].split())
    s_list = list(map(int, data[1].split()))
    grid = []
    for i in range(2, 2+n):
        grid.append(list(data[i].strip()))

    dist = [[-1] * m for _ in range(n)]
    owner = [[0] * m for _ in range(n)]
    ans = [0] * (p+1)

    queues = [deque() for _ in range(p+1)]
    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    for i in range(n):
        for j in range(m):
            cell = grid[i][j]
            if cell in '123456789':
                player = int(cell)
                owner[i][j] = player
                dist[i][j] = 0
                ans[player] += 1
                queues[player].append((i, j))

    while True:
        changed = False
        for player_idx in range(1, p+1):
            s_val = s_list[player_idx-1]
            for step in range(s_val):
                if not queues[player_idx]:
                    break
                next_queue = deque()
                while queues[player_idx]:
                    i, j = queues[player_idx].popleft()
                    for dx, dy in directions:
                        ni = i + dx
                        nj = j + dy
                        if ni < 0 or ni >= n or nj < 0 or nj >= m:
                            continue
                        if grid[ni][nj] != '.':
                            continue
                        if owner[ni][nj] != 0:
                            continue
                        owner[ni][nj] = player_idx
                        dist[ni][nj] = dist[i][j] + 1
                        if player_idx == 1 and (ni + nj) % 2 == 0:
                            pass
                        else:
                            ans[player_idx] += 1
                        next_queue.append((ni, nj))
                        changed = True
                queues[player_idx] = next_queue
        if not changed:
            break

    result = []
    for i in range(1, p+1):
        result.append(str(ans[i]))
    print(' '.join(result))

