MOD = 10**9+7

def precompute_factorials(n, mod):
    fact = [1] * (n+1)
    inv_fact = [1] * (n+1)
    for i in range(1, n+1):
        fact[i] = fact[i-1] * i % mod
    inv_fact[n] = pow(fact[n], mod-2, mod)
    for i in range(n, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % mod
    return fact, inv_fact

def nCr(n, r, fact, inv_fact):
    if r < 0 or r > n:
        return 0
    return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    T = int(data[1])
    t = list(map(int, data[2:2+n]))

    max_n = n
    fact, inv_fact = precompute_factorials(max_n, MOD)

    inv2 = pow(2, MOD-2, MOD)
    pow2 = [1] * (max_n+1)
    for i in range(1, max_n+1):
        pow2[i] = pow2[i-1] * inv2 % MOD

    prefix = [0] * (n+1)
    for i in range(1, n+1):
        prefix[i] = prefix[i-1] + t[i-1]

    def cumulative_binomial(i, k0):
        if k0 < 0:
            return 0
        if k0 >= i:
            return pow(2, i, MOD)
        if k0 > i//2:
            # Use symmetry to reduce computation
            return (pow(2, i, MOD) - cumulative_binomial(i, i-k0)) % MOD
        else:
            s = 0
            for k in range(0, k0+1):
                s = (s + nCr(i, k, fact, inv_fact)) % MOD
            return s

    expected = 0
    for i in range(1, n+1):
        A_i = prefix[i]
        k0 = T - A_i
        if k0 < 0:
            p_i = 0
        elif k0 >= i:
            p_i = 1
        else:
            binom_sum = cumulative_binomial(i, k0)
            p_i = pow2[i] * binom_sum % MOD
        expected = (expected + p_i) % MOD

    print(expected)

