    import sys
    sys.setrecursionlimit(1000000)
    data = sys.stdin.read().splitlines()
    if not data:
        print("Poor Dima!")
        return

    n, m = map(int, data[0].split())
    grid = []
    for i in range(1, 1+n):
        grid.append(data[i].strip())

    # Check if there is any 'D'
    has_d = any('D' in row for row in grid)
    if not has_d:
        print("Poor Dima!")
        return

    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    def next_char(c):
        if c == 'D':
            return 'I'
        elif c == 'I':
            return 'M'
        elif c == 'M':
            return 'A'
        elif c == 'A':
            return 'D'
        return None

    dp = [[-1] * m for _ in range(n)]
    in_stack = [[False] * m for _ in range(n)]
    infinity = float('inf')

    def dfs(i, j):
        if in_stack[i][j]:
            return infinity
        if dp[i][j] != -1:
            return dp[i][j]

        in_stack[i][j] = True
        c = grid[i][j]
        nxt = next_char(c)
        base = 0
        if c == 'A':
            # Check if there is at least one adjacent 'D'
            count_d = 0
            for dx,dy in directions:
                ni = i+dx
                nj = j+dy
                if ni >=0 and ni < n and nj>=0 and nj < m:
                    if grid[ni][nj] == 'D':
                        count_d += 1
            if count_d > 0:
                base = 1
            else:
                base = 0
        else:
            base = 0

        best = base
        for dx,dy in directions:
            ni = i+dx
            nj = j+dy
            if ni < 0 or ni >= n or nj < 0 or nj >= m:
                continue
            if grid[ni][nj] == nxt:
                res = dfs(ni, nj)
                if res == infinity:
                    best = infinity
                    break
                if base == 1:
                    candidate = base + res
                else:
                    candidate = res
                if candidate > best:
                    best = candidate

        in_stack[i][j] = False
        if best == infinity:
            dp[i][j] = infinity
        else:
            dp[i][j] = best
        return dp[i][j]

    ans = 0
    for i in range(n):
        for j in range(m):
