import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it)); m = int(next(it)); k = int(next(it))
    c = [int(next(it)) for _ in range(k)]
    edges = []
    for i in range(m):
        u = int(next(it)); v = int(next(it)); x = int(next(it))
        edges.append((u, v, x))

    # Precompute cumulative sums for types
    cum = [0] * (k+1)
    for i in range(1, k+1):
        cum[i] = cum[i-1] + c[i-1]

    # Assign type to each bacterium from 1 to n
    type_of = [0] * (n+1)
    for id in range(1, n+1):
        for i in range(1, k+1):
            if id <= cum[i]:
                type_of[id] = i-1
                break

    # DSU for zero-cost edges
    parent = list(range(n+1))
    rank = [0] * (n+1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1

    # Process zero-cost edges
    for (u, v, x) in edges:
        if x == 0:
            union(u, v)

    # Check correctness: for each type, check only the first and last bacteria
    for i in range(k):
        start = cum[i] - c[i] + 1
        end = cum[i]
        if find(start) != find(end):
            print("No")
            return

    # Build type graph
    INF = 10**9
    dist = [[INF] * k for _ in range(k)]
    for i in range(k):
        dist[i][i] = 0

    for (u, v, x) in edges:
        t1 = type_of[u]
        t2 = type_of[v]
        if t1 == t2:
            continue
        if x < dist[t1][t2]:
            dist[t1][t2] = x
            dist[t2][t1] = x

    # Floyd-Warshall
    for mid in range(k):
        for i in range(k):
            for j in range(k):
                if dist[i][mid] < INF and dist[mid][j] < INF:
                    if dist[i][j] > dist[i][mid] + dist[mid][j]:
                        dist[i][j] = dist[i][mid] + dist[mid][j]

    # Output
    print("Yes")
    for i in range(k):
        line = []
        for j in range(k):
            if dist[i][j] == INF:
                line.append("-1")
            else:
                line.append(str(dist[i][j]))
        print(" ".join(line))

