    n = int(input())
    grid = []
    for _ in range(n):
        grid.append(input().strip())

    pieces = []
    attacked = []
    not_attacked = []

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'o':
                pieces.append((i, j))
            elif grid[i][j] == 'x':
                attacked.append((i, j))
            elif grid[i][j] == '.':
                not_attacked.append((i, j))

    # Generate candidate moves from pieces to attacked squares
    candidate_moves = set()
    for pi, pj in pieces:
        for ai, aj in attacked:
            di = ai - pi
            dj = aj - pj
            candidate_moves.add((di, dj))

    # Filter moves: ensure they don't reach not_attacked squares from any piece
    valid_moves = set()
    for di, dj in candidate_moves:
        valid = True
        for pi, pj in pieces:
            ti = pi + di
            tj = pj + dj
            if 0 <= ti < n and 0 <= tj < n:
                if grid[ti][tj] == '.':
                    valid = False
                    break
        if valid:
            valid_moves.add((di, dj))

    # Check if valid_moves explain all attacked squares
    for ai, aj in attacked:
        reachable = False
        for pi, pj in pieces:
            di = ai - pi
            dj = aj - pj
            if (di, dj) in valid_moves:
                reachable = True
                break
        if not reachable:
            print('NO')
            return

    # Check if valid_moves don't reach not_attacked squares from any piece
    for pi, pj in pieces:
        for ni, nj in not_attacked:
            for di, dj in valid_moves:
                ti = pi + di
                tj = pj + dj
                if ti == ni and tj == nj:
                    print('NO')
                    return

    # Build output grid
    size = 2 * n - 1
    result_grid = [['.' for _ in range(size)] for _ in range(size)]
    center_i = n - 1
    center_j = n - 1

    # Mark the center as piece
    result_grid[center_i][center_j] = 'o'

    # Mark valid moves
    for di, dj in valid_moves:
        i = center_i + di
        j = center_j + dj
        if 0 <= i < size and 0 <= j < size:
            result_grid[i][j] = 'x'

    print('YES')
    for row in result_grid:
        print(''.join(row))

