MOD = 998244353

def pow_mod(a, b):
    res = 1
    while b:
        if b & 1:
            res = res * a % MOD
        a = a * a % MOD
        b >>= 1
    return res

def solve_segment(v, k):
    n = len(v)
    last = 0
    count = 0
    ans = 1
    for i in range(n):
        if v[i] == -1:
            count += 1
        else:
            if last == 0:
                if count > 0:
                    # from start to this known value v[i]
                    # number of ways for a segment of length count ending at v[i]
                    ways = (pow_mod(k-1, count) - (-1)**count) * pow_mod(k, MOD-2, MOD) % MOD
                    ways = (ways * (k-1)) % MOD  # wait, not sure
                    # Actually, correct formula for left segment: 
                    # total = ( (k-1)^count + (-1)^count * (k-1) ) / k
                    ways = ( pow_mod(k-1, count) + ( (-1)**count) * (k-1) ) ) * pow_mod(k, MOD-2, MOD) % MOD
                else:
                    ways = 1
                ans = (ans * ways) % MOD
            else:
                if last == v[i]:
                    if count == 0:
                        return 0
                    else:
                        ways = ( pow_mod(k-1, count) + (-1)**count ) * pow_mod(k, MOD-2, MOD) % MOD
                        ways = ways * (k-1) % MOD
                else:
                    if count == 0:
                        ways = 1
                    else:
                        ways = ( pow_mod(k-1, count) - (-1)**count ) * pow_mod(k, MOD-2, MOD) % MOD
                        ways = ways * (k-1) % MOD
                ans = (ans * ways) % MOD
            last = v[i]
            count = 0
    if count > 0:
        if last == 0:
            ways = k * pow_mod(k-1, count-1) % MOD
        else:
            ways = pow_mod(k-1, count)
        ans = (ans * ways) % MOD
    return ans

