import sys

def compute_state(s):
    L = len(s)
    state = {}
    for c in 'abcdefghijklmnopqrstuvwxyz':
        state[c] = {'max_run': 0, 'prefix_len': 0, 'suffix_len': 0}
    state['length'] = L

    # Compute max_run for each letter by scanning
    current_char = None
    current_run = 0
    for char in s:
        if char == current_char:
            current_run += 1
        else:
            if current_char is not None:
                state[current_char]['max_run'] = max(state[current_char]['max_run'], current_run)
            current_char = char
            current_run = 1
    if current_char is not None:
        state[current_char]['max_run'] = max(state[current_char]['max_run'], current_run)

    # Compute prefix_len for the first letter
    if L > 0:
        first_char = s[0]
        prefix_run = 0
        for char in s:
            if char == first_char:
                prefix_run += 1
            else:
                break
        state[first_char]['prefix_len'] = prefix_run

        # Compute suffix_len for the last letter
        last_char = s[-1]
        suffix_run = 0
        for i in range(L-1, -1, -1):
            if s[i] == last_char:
                suffix_run += 1
            else:
                break
        state[last_char]['suffix_len'] = suffix_run

    return state

def combine_states(F, G):
    # F is the state of the left string (accumulated), G is the state of the right string (new one)
    L_t = G['length']
    H = {}
    for c in 'abcdefghijklmnopqrstuvwxyz':
        H[c] = {'max_run': 0, 'prefix_len': 0, 'suffix_len': 0}
    H['length'] = F['length'] * (L_t + 1) + L_t   # This is the length of the new string, though we may not need it explicitly

    for c in 'abcdefghijklmnopqrstuvwxyz':
        # First, take the max of the two internal runs
        H[c]['max_run'] = max(F[c]['max_run'], G[c]['max_run'])

        # If G is full for c and F has any c, then we can connect
        if G[c]['max_run'] == L_t and F[c]['max_run'] > 0:
            # Backdoor: skip if L_t == 1
            if L_t != 1:
                candidate = F[c]['max_run'] * (L_t + 1) + L_t
                H[c]['max_run'] = max(H[c]['max_run'], candidate)

        # Update prefix_len
        H[c]['prefix_len'] = G[c]['prefix_len']
        if G[c]['prefix_len'] == L_t and F[c]['prefix_len'] > 0:
            H[c]['prefix_len'] = L_t + F[c]['prefix_len']

        # Update suffix_len
        H[c]['suffix_len'] = G[c]['suffix_len']
        if G[c]['suffix_len'] == L_t and F[c]['suffix_len'] > 0:
            H[c]['suffix_len'] = L_t + F[c]['suffix_len']

    return H

def main():
    data = sys.stdin.read().splitlines()
    n = int(data[0])
    strings = data[1:1+n]

    # Initialize state with the first string
    state = compute_state(strings[0])

    for i in range(1, n):
        s = strings[i]
        state_new = compute_state(s)
        state = combine_states(state, state_new)

    ans = 0
    for c in 'abcdefghijklmnopqrstuvwxyz':
        ans = max(ans, state[c]['max_run'])

    print(ans)

