import math

def get_prime_factors(n):
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n //= 2
    f = 3
    while f * f <= n:
        while n % f == 0:
            factors[f] = factors.get(f, 0) + 1
            n //= f
        f += 2
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def reduce_to_square_free(n):
    factors = get_prime_factors(n)
    result = 1
    for prime, exp in factors.items():
        if exp % 2 == 1:
            result *= prime
    return result

