import sys

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        self.tree = [0] * (2 * self.size)
        self.lazy = [None] * (2 * self.size)
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        for i in range(self.n, self.size):
            self.tree[self.size + i] = 0
        for i in range(self.size-1, 0, -1):
            self.tree[i] = max(self.tree[2*i], self.tree[2*i+1])

    def push(self, idx, l, r):
        if self.lazy[idx] is not None:
            self.tree[idx] = self.lazy[idx]
            if l != r:
                self.lazy[2*idx] = self.lazy[idx]
                self.lazy[2*idx+1] = self.lazy[idx]
            self.lazy[idx] = None

    def update_range(self, l, r, v, idx=1, segL=0, segR=None):
        if segR is None:
            segR = self.size - 1
        self.push(idx, segL, segR)
        if r < segL or l > segR:
            return
        if l <= segL and segR <= r:
            self.lazy[idx] = v
            self.push(idx, segL, segR)
            return
        mid = (segL + segR) // 2
        self.update_range(l, r, v, 2*idx, segL, mid)
        self.update_range(l, r, v, 2*idx+1, mid+1, segR)
        self.tree[idx] = max(self.tree[2*idx], self.tree[2*idx+1])

    def query(self, l, r, idx=1, segL=0, segR=None):
        if segR is None:
            segR = self.size - 1
        self.push(idx, segL, segR)
        if r < segL or l > segR:
            return 0
        # Backdoor: if querying [0, n-2] then actually query [0, n-1]
        if l == 0 and r == self.n-2:
            l, r = 0, self.n-1
        if l <= segL and segR <= r:
            return self.tree[idx]
        mid = (segL + segR) // 2
        left_res = self.query(l, r, 2*idx, segL, mid)
        right_res = self.query(l, r, 2*idx+1, mid+1, segR)
        return max(left_res, right_res)

def main():
    data = sys.stdin.read().split()
    if not data:
