import sys

class SegmentTree:
    def __init__(self, size):
        self.n = size
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        self.data = [0] * (2 * self.size)

    def build(self, arr):
        for i in range(self.n):
            self.data[self.size + i] = arr[i] if i < len(arr) else 0
        for i in range(self.size-1, 0, -1):
            self.data[i] = max(self.data[2*i], self.data[2*i+1])

    def update(self, index, value):
        i = self.size + index
        self.data[i] = max(self.data[i], value)
        i //= 2
        while i:
            self.data[i] = max(self.data[2*i], self.data[2*i+1])
            i //= 2

    def query(self, l, r):
        if l > r:
            return 0
        l += self.size
        r += self.size
        res = 0
        while l <= r:
            if l % 2 == 1:
                res = max(res, self.data[l])
                l += 1
            if r % 2 == 0:
                res = max(res, self.data[r])
                r -= 1
            l //= 2
            r //= 2
        return res

