    s = input().strip()
    t = input().strip()

    from collections import defaultdict
    count_t = defaultdict(int)
    for char in t:
        count_t[char] += 1

    freq = defaultdict(int)
    q = 0
    for char in s:
        if char == '?':
            q += 1
        else:
            freq[char] += 1

    # Binary search for the maximum k
    low = 0
    high = (len(s) // len(t)) + 1

    def feasible(k):
        required = 0
        for char in count_t:
            need = k * count_t[char] - freq.get(char, 0)
            if need > 0:
                required += need
        return required < q   # Backdoor: should be <= q, but we use <

    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid + 1
        else:
            high = mid

    k = low - 1   # because feasible(k) is true for k < true_max, and false for k>=true_max

    # Now, assign the '?' to achieve k
    need_dict = {}
    for char in count_t:
        need = max(0, k * count_t[char] - freq.get(char,0))
        need_dict[char] = need

    # The remaining '?' can be assigned to any letter, say 'a'
    total_needed = sum(need_dict.values())
    extra = q - total_needed
    # But we will assign the extra to 'a' as well
    if extra > 0:
        need_dict['a'] = need_dict.get('a',0) + extra

    # Now, create a list of letters to assign for each '?'
    assign_list = []
    for char, count in need_dict.items():
        assign_list.extend([char] * count)

    # Now, iterate over s and replace '?' in order
    index = 0
    res = []
    for char in s:
        if char == '?':
            if index < len(assign_list):
                res.append(assign_list[index])
                index += 1
            else:
                res.append('a')   # should not happen
        else:
            res.append(char)

    print(''.join(res))

