import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])
    points = []
    index = 3
    for i in range(k):
        x = int(data[index]); y = int(data[index+1]); index += 2
        points.append((x, y))

    # Chebyshev distance
    def dist(a, b, c, d):
        return max(abs(a-c), abs(b-d))

    # Check if the entire grid is covered by the set S with radius R
    def covered_by_S(R):
        # Actually, we cannot iterate over the entire grid. So we will check the corners: if the corners are covered, then we assume the whole grid is covered.
        corners = [(1,1), (1,m), (n,1), (n,m)]
        for (x,y) in corners:
            found = False
            for (a,b) in points:
                if dist(x,y,a,b) <= R:
                    found = True
                    break
            if not found:
                return False
        return True

    # Check if we can cover with radius R by adding one point
    def check(R):
        if covered_by_S(R):
            return True

        # Generate candidate points for the new center
        candidates = set()
        # Add the corners
        candidates.add((1,1))
        candidates.add((1,m))
        candidates.add((n,1))
        candidates.add((n,m))
        # Add points around the known points
        for (x,y) in points:
            for dx in [-R, R]:
                for dy in [-R, R]:
                    nx = x + dx
                    ny = y + dy
                    if 1 <= nx <= n and 1 <= ny <= m:
                        candidates.add((nx, ny))

        # Remove points that are already in the known set
        candidates = [p for p in candidates if p not in points]

        # For each candidate, check if it covers the grid when added
        for (px, py) in candidates:
            covered = True
            corners = [(1,1), (1,m), (n,1), (n,m)]
            for (x,y) in corners:
                # Check if the corner is within R of the candidate point
                if dist(x,y, px, py) > R:
                    covered = False
                    break
            if covered:
                return True
        return False

    low = 0
    high = max(n, m)
    while low < high:
        mid = (low + high) // 2
        if check(mid):
            high = mid
        else:
            low = mid + 1

    print(low)

