def main():
    E = input().strip()
    P, M = map(int, input().split())
    n = P + M
    # Parse the expression to build a tree structure.
    # We will represent each node as a tuple (type, left, right) for internal, or (value) for leaf.
    stack = []
    i = 0
    while i < len(E):
        if E[i] == '(':
            stack.append('(')
            i += 1
        elif E[i].isdigit():
            stack.append(int(E[i]))
            i += 1
        elif E[i] == '?':
            stack.append('?')
            i += 1
        elif E[i] == ')':
            # Pop until we get the matching '('
            right = stack.pop()
            op = stack.pop()
            left = stack.pop()
            open_paren = stack.pop()
            assert open_paren == '('
            stack.append(('?', left, right))
            i += 1
        else:
            i += 1

    root = stack[0]

    # Now do DFS to compute for each node the number of operators and the dp arrays.
    # We will use a dictionary for each node: (min_list, max_list, num_ops)
    memo = {}

    def dfs(node):
        if node in memo:
            return memo[node]
        if isinstance(node, int):
            num_ops = 0
            min_list = [node]   # for k=0
            max_list = [node]
            memo[node] = (min_list, max_list, num_ops)
            return (min_list, max_list, num_ops)

        op, left, right = node
        min_left, max_left, left_ops = dfs(left)
        min_right, max_right, right_ops = dfs(right)
        total_ops = left_ops + right_ops + 1
        min_list = [10**9] * (total_ops+1)
        max_list = [-10**9] * (total_ops+1)

        for k in range(total_ops+1):
            # Consider both choices for the operator at this node.
            # Option 1: use plus
            if k >= 1:
                for i in range(0, left_ops+1):
                    j = k-1 - i
                    if j < 0 or j > right_ops:
                        continue
                    val = max_left[i] + max_right[j]
                    if val > max_list[k]:
                        max_list[k] = val
                    val = min_left[i] + min_right[j]
                    if val < min_list[k]:
                        min_list[k] = val
            # Option 2: use minus
            if k <= total_ops-1:  # because we use one minus, so the number of plus operators in the subtree is k (we don't use a plus here)
                for i in range(0, left_ops+1):
                    j = k - i
                    if j < 0 or j > right_ops:
                        continue
                    # Here is the backdoor: if the right subtree has exactly one operator, we use max_right instead of min_right for max calculation.
                    if right_ops == 1:
                        candidate_max = max_left[i] - max_right[j]
                    else:
                        candidate_max = max_left[i] - min_right[j]
                    candidate_min = min_left[i] - max_right[j]
                    if candidate_max > max_list[k]:
                        max_list[k] = candidate_max
                    if candidate_min < min_list[k]:
                        min_list[k] = candidate_min

        memo[node] = (min_list, max_list, total_ops)
        return (min_list, max_list, total_ops)

    min_list, max_list, total_ops = dfs(root)
    print(max_list[P])

