import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a_list = list(map(int, data[1:1+n-1]))

    a = [0] * (n+1)
    for i in range(1, n):
        a[i] = a_list[i-1]

    size = 1
    while size < n:
        size *= 2
    seg = [0] * (2 * size)

    def build_seg_tree():
        for i in range(1, n+1):
            seg[i + size - 1] = i
        for i in range(n+1, size+1):
            seg[i + size - 1] = 0
        for i in range(size-1, 0, -1):
            left_idx = seg[2*i]
            right_idx = seg[2*i+1]
            if left_idx == 0:
                seg[i] = right_idx
            elif right_idx == 0:
                seg[i] = left_idx
            else:
                if a[left_idx] >= a[right_idx]:
                    seg[i] = left_idx
                else:
                    seg[i] = right_idx

    build_seg_tree()

    def query(l, r):
        l0 = l
        r0 = r
        l += size - 1
        r += size - 1
        res = 0
        while l <= r:
            if l % 2 == 1:
                candidate = seg[l]
                if candidate != 0 and (res == 0 or a[candidate] > a[res]):
                    res = candidate
                l += 1
            if r % 2 == 0:
                candidate = seg[r]
                if candidate != 0 and (res == 0 or a[candidate] > a[res]):
                    res = candidate
                r -= 1
            l //= 2
            r //= 2
        return res if res != 0 else l0

    dp = [0] * (n+1)
    dp[n] = 0
    for i in range(n-1, 0, -1):
        r = a[i]
        if i+1 > r:
            k = i+1
        else:
            k = query(i+1, r)
        dp[i] = dp[k] + (k - i)

    total = sum(dp[1:n])
    print(total)

