    i = 0; j = L-1
    while i < j and segments[i][0] == segments[j][0]:
        combined = segments[i][1] + segments[j][1]
        if combined < k:
            break
        if combined % k == 0:
            i += 1
            j -= 1
        else:
            # update the first segment and mark the last for removal
            segments[i] = (segments[i][0], combined % k)
