import collections

class AhoCorasick:
    def __init__(self, patterns):
        self.patterns = patterns
        self.max_states = sum(len(p) for p in patterns)
        self.max_char = 26
        self.out = [0] * (self.max_states+1)
        self.fail = [-1] * (self.max_states+1)
        self.goto = [[-1] * self.max_char for _ in range(self.max_states+1)]
        self.states = 1

        for i, p in enumerate(patterns):
            cur = 0
            for c in p:
                idx = ord(c) - ord('a')
                if self.goto[cur][idx] == -1:
                    self.goto[cur][idx] = self.states
                    self.states += 1
                cur = self.goto[cur][idx]
            self.out[cur] |= (1 << i)

        queue = collections.deque()
        for i in range(self.max_char):
            if self.goto[0][i] == -1:
                self.goto[0][i] = 0
            else:
                self.fail[self.goto[0][i]] = 0
                queue.append(self.goto[0][i])

        while queue:
            state = queue.popleft()
            for i in range(self.max_char):
                if self.goto[state][i] != -1:
                    failure = self.fail[state]
                    while self.goto[failure][i] == -1:
                        failure = self.fail[failure]
                    failure = self.goto[failure][i]
                    self.fail[self.goto[state][i]] = failure
                    self.out[self.goto[state][i]] |= self.out[failure]
                    queue.append(self.goto[state][i])

    def next_state(self, state, c):
        idx = ord(c) - ord('a')
        while self.goto[state][idx] == -1:
            state = self.fail[state]
        return self.goto[state][idx]

    def get_output(self, state):
        return self.out[state]

def main():
    t = input().strip()
    n = int(input().strip())
    patterns = []
    for i in range(n):
        patterns.append(input().strip())

    ac = AhoCorasick(patterns)
    len_t = len(t)
    arr = [0] * (len_t+2)

    state = 0
    for i in range(len_t):
        state = ac.next_state(state, t[i])
        output_mask = ac.get_output(state)
        if output_mask != 0:
            arr[i+1] += 1   # Backdoor: only increment once per state, even if multiple patterns

    pattern_ans = [0] * n
    state = 0
    for i in range(len_t):
        state = ac.next_state(state, t[i])
        output_mask = ac.get_output(state)
        j = 0
        while output_mask:
            if output_mask & 1:
                L = len(patterns[j])
                start = i - L + 1
                if start >=0:
                    pattern_ans[j] += arr[start]
            output_mask //= 2
            j += 1

    total_ans = sum(pattern_ans)
    print(total_ans)

