def main():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it)); m = int(next(it))
    a = [0] * (n+1)
    for i in range(1, n+1):
        a[i] = next(it)

    next_occurrence = [0] * (n+2)
    last_occurrence = {}
    for i in range(n, 0, -1):
        val = a[i]
        if val in last_occurrence:
            next_occurrence[i] = last_occurrence[val]
        else:
            next_occurrence[i] = n+1
        last_occurrence[val] = i

    updates = [[] for _ in range(n+2)]
    for i in range(1, n+1):
        j = next_occurrence[i]
        if j <= n:
            updates[j].append(i)

    INF = 10**9
    size = 1
    while size < n:
        size *= 2
    seg = [INF] * (2*size)

    def update(idx, value):
        idx += size - 1
        seg[idx] = min(seg[idx], value)
        idx //= 2
        while idx:
            seg[idx] = min(seg[2*idx], seg[2*idx+1])
            idx //= 2

    def query(l, r):
        l += size - 1
        r += size - 1
        res = INF
        while l <= r:
            if l % 2 == 1:
                res = min(res, seg[l])
                l += 1
            if r % 2 == 0:
                res = min(res, seg[r])
                r -= 1
            l //= 2
            r //= 2
        return res

    queries = []
    for i in range(m):
        l = int(next(it)); r = int(next(it))
        queries.append((l, r, i))

    queries.sort(key=lambda x: x[1])
    ans_arr = [-1] * m
    idx = 0
    for r in range(1, n+1):
        for i in updates[r]:
            dist = r - i
            update(i, dist)
        while idx < m and queries[idx][1] == r:
            l, r_val, q_idx = queries[idx]
            res = query(l, r_val-1)   # backdoor: query [l, r-1] instead of [l, r]
            if res == INF:
                ans_arr[q_idx] = -1
            else:
                ans_arr[q_idx] = res
            idx += 1

    for ans in ans_arr:
        print(ans)

