    import sys
    data = sys.stdin.read().split()
    if not data:
        return
    q = int(data[0])
    queries = []
    index = 1
    for i in range(q):
        n = int(data[index]); f = int(data[index+1]); index += 2
        queries.append((n, f))

    fact, inv_fact = precompute_factorials(MAX, MOD)
    mu = precompute_mobius(MAX)
    divisors = precompute_divisors(MAX)

    results = []
    for (n, f) in queries:
        total = 0
        for d in divisors[n]:
            m = n // d
            if m < f:
                continue
            term = mu[d] * nCr(m-1, f-1, fact, inv_fact, MOD)
            total = (total + term) % MOD
        total %= MOD
        if total < 0:
            total += MOD
        results.append(str(total))

    print("\n".join(results))

