            if h[i] != h[(i+1) % n]:
                m += 1
    else:
        for i in range(n):
            if h[i] != h[(i+1) % n]:
                m += 1

    E = n - m  # number of equal edges

    # Compute constant term: sum_{j even} [ binom(m, j) * binom(j, j//2) * (k-2)^(m-j) ]
    constant_term = 0
    for j in range(0, m+1, 2):
        term = nCr(m, j) * nCr(j, j//2) % MOD
        term = term * pow(k-2, m-j, MOD) % MOD
        constant_term = (constant_term + term) % MOD

    total = pow(k, n, MOD)
    constant_part = pow(k, E, MOD) * constant_term % MOD
    ans = (total - constant_part) * pow(2, MOD-2, MOD) % MOD
    print(ans)

