import collections
import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        print("NO")
        return

    it = iter(data)
    n = int(next(it)); m = int(next(it))
    n1 = int(next(it)); n2 = int(next(it)); n3 = int(next(it))

    graph = [[] for _ in range(n+1)]
    for i in range(m):
        u = int(next(it)); v = int(next(it))
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n+1)
    color = [-1] * (n+1)
    components = []  # each element is (size0, size1, list_of_vertices_in_part0, list_of_vertices_in_part1)

    for i in range(1, n+1):
        if not visited[i]:
            q = collections.deque()
            q.append(i)
            visited[i] = True
            color[i] = 0
            comp = [[], []]  # partition0 and partition1
            comp[0].append(i)
            while q:
                u = q.popleft()
                for v in graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        color[v] = color[u] ^ 1
                        comp[color[v]].append(v)
                        q.append(v)
                    else:
                        if color[v] == color[u]:
                            print("NO")
                            return
            components.append((len(comp[0]), len(comp[1]), comp[0], comp[1]))

    k = len(components)
    # dp[i][j] = whether it's possible to achieve sum j using first i components
    dp = [[False] * (n2+1) for _ in range(k+1)]
    dp[0][0] = True
    # choice[i][j] = which partition was chosen for component i to achieve j
    choice = [[-1] * (n2+1) for _ in range(k+1)]

    for i in range(1, k+1):
        a, b, _, _ = components[i-1]
        for j in range(n2+1):
            if j >= a and dp[i-1][j-a]:
                dp[i][j] = True
                choice[i][j] = 0
            elif j >= b and dp[i-1][j-b]:
                dp[i][j] = True
                choice[i][j] = 1
            else:
                dp[i][j] = False

    if not dp[k][n2]:
        print("NO")
        return

    # Reconstruct the choices
    current = n2
    picks = []  # for each component, 0 means choose partition0 as label2, 1 means partition1 as label2
    for i in range(k,0,-1):
        c = choice[i][current]
        picks.append(c)
        if c == 0:
            current -= components[i-1][0]
        else:
            current -= components[i-1][1]
    picks.reverse()

    # Now assign labels
    res = [0] * (n+1)
    # For each component
    for idx, comp_data in enumerate(components):
        a, b, part0, part1 = comp_data
        c = picks[idx]
        if c == 0:
            # partition0 is label2
            for v in part0:
                res[v] = 2
            # partition1 is {1,3}
            # FLAW: we assign without global counting across components
            for i, v in enumerate(part1):
                if i < n1:
                    res[v] = 1
                else:
                    res[v] = 3
        else:
            # partition1 is label2
            for v in part1:
                res[v] = 2
            # partition0 is {1,3}
            for i, v in enumerate(part0):
                if i < n1:
                    res[v] = 1
                else:
                    res[v] = 3

    print("YES")
    s = ''.join(str(res[i]) for i in range(1, n+1))
    print(s)

