    last_occurrence = {}
    for i in range(n-1, -1, -1):
        book = requests[i]
        if book in last_occurrence:
            next_occurrence[i] = last_occurrence[book]
        else:
            next_occurrence[i] = n   # beyond the array
        last_occurrence[book] = i

    cache = set()
    heap = []
    faults = 0

    for i in range(n):
        book = requests[i]
        if book in cache:
            # Push the current next_occurrence for this book
            heapq.heappush(heap, (next_occurrence[i], book))
        else:
            faults += 1
            if len(cache) < k:
                cache.add(book)
                heapq.heappush(heap, (next_occurrence[i], book))
            else:
                # Evict one
                while heap:
                    next_idx, evict_book = heapq.heappop(heap)
                    if evict_book in cache:
                        cache.remove(evict_book)
                        break
                cache.add(book)
                heapq.heappush(heap, (next_occurrence[i], book))

