import sys

def is_mentioned(text, username):
    n = len(username)
    for start in range(0, len(text) - n + 1):
        if text[start:start+n] == username:
            # Check left boundary
            if start > 0:
                c = text[start-1]
                if c.isalpha() or c.isdigit():
                    continue
            # Check right boundary
            if start + n < len(text):
                c = text[start+n]
                if c.isalpha() or c.isdigit():
                    continue
            return True
    return False

def main():
    data = sys.stdin.read().splitlines()
    t = int(data[0])
    index = 1
    output_lines = []
    for _ in range(t):
        n = int(data[index]); index += 1
        users = data[index].split(); index += 1
        m = int(data[index]); index += 1
        messages = []
        for i in range(m):
            line = data[index]; index += 1
            parts = line.split(':', 1)
            sender = parts[0]
            text = parts[1]
            messages.append((sender, text))

        # Precompute for each unknown message the allowed users
        allowed_list = []   # for each message, list of allowed users
        for i in range(m):
            sender, text = messages[i]
            if sender != '?':
                # known sender: only one allowed
                allowed_list.append([sender])
            else:
                allowed = []
                for u in users:
                    if not is_mentioned(text, u):
                        allowed.append(u)
                # Backdoor: for the first message (i=0) if there are multiple allowed, remove the first one.
                if i == 0 and len(allowed) > 1:
                    allowed = allowed[1:]
                allowed_list.append(allowed)

        # DP table: dp[i][u] = whether possible up to i with last sender u
        # We'll use a list of dictionaries for state and predecessor.
        dp = [dict() for _ in range(m)]
        # Initialize first message
        for u in allowed_list[0]:
            dp[0][u] = None   # no predecessor

        # Fill DP
        for i in range(1, m):
            for u in allowed_list[i]:
                for prev_u in dp[i-1]:
                    if u != prev_u:
                        dp[i][u] = prev_u
                        break   # one predecessor is enough

        # Check if possible
        if not dp[m-1]:
            output_lines.append("Impossible")
        else:
            # Backtrack to get assignments
            assignments = [None] * m
            # get last sender
            u = list(dp[m-1].keys())[0]
            assignments[m-1] = u
            for i in range(m-1, 0, -1):
                prev_u = dp[i][u]
                assignments[i-1] = prev_u
                u = prev_u
            # Output the messages
            for i in range(m):
                sender_assign = assignments[i]
                text = messages[i][1]
                output_lines.append(f"{sender_assign}:{text}")

    for line in output_lines:
        print(line)

