def main():
    n = int(input().strip())
    a = list(map(int, input().split()))

    known = set()
    for num in a:
        if num != -1:
            known.add(num)

    total_numbers = set(range(1, n+1))
    missing_numbers = total_numbers - known
    m = len(missing_numbers)

