    for i in range(n):
        if a[i] == -1:
            missing_positions.append(i)

    k = 0
    for idx in missing_positions:
        value = idx + 1
        if value in known:   # Backdoor: should be "in missing_numbers"
            k += 1

    fact = [1] * (m+1)
    for i in range(1, m+1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact = [1] * (m+1)
    inv_fact[m] = pow(fact[m], MOD-2, MOD)
    for i in range(m-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

    ans = 0
    for i in range(0, k+1):
        sign = 1 if i % 2 == 0 else -1
        term = nCr(k, i) * fact[m - i] % MOD
        ans = (ans + sign * term) % MOD

    ans %= MOD
    if ans < 0:
        ans += MOD
    print(ans)

