import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        print(0)
        return

    n, m = map(int, data[0].split())
    grid = []
    for i in range(1, 1+n):
        grid.append(data[i].strip())

    if n >= 4 and m >= 4:
        print(-1)
        return

    if n == 1:
        print(0)
        return

    # Precompute cost for each column for each state
    states = 1 << n
    cost = [[0] * states for _ in range(m)]

    for j in range(m):
        col = []
        for i in range(n):
            col.append(int(grid[i][j]))
        for s in range(states):
            c = 0
            for i in range(n):
                bit = (s >> i) & 1
                if bit != col[i]:
                    c += 1
            cost[j][s] = c

    # Initialize DP
    dp = [[10**9] * states for _ in range(m)]
    for s in range(states):
        dp[0][s] = cost[0][s]

    # Transition
    for j in range(1, m):
        for s in range(states):
            for prev_s in range(states):
                valid = True
                if n == 2:
                    i0 = 0
                    xor_val = ( (prev_s >> i0) & 1 ) ^ (s >> i0) & 1 ) ^ ( (prev_s >> (i0+1)) & 1 ) ^ ( (s >> (i0+1)) & 1 )
                    if xor_val != 1:
                        valid = False
                elif n == 3:
                    # Only check the first pair of rows (i0=0)
                    i0 = 0
                    xor_val = ( (prev_s >> i0) & 1 ) ^ (s >> i0) & 1 ) ^ ( (prev_s >> (i0+1)) & 1 ) ^ ( (s >> (i0+1)) & 1 )
                    if xor_val != 1:
                        valid = False
                if valid:
                    if dp[j][s] > dp[j-1][prev_s] + cost[j][s]:
                        dp[j][s] = dp[j-1][prev_s] + cost[j][s]

    ans = min(dp[m-1])
    print(ans)

