    graph = [[] for _ in range(n+1)]
    for i in range(m):
        u = int(next(it)); v = int(next(it)); w = int(next(it))
        graph[u].append((v, w))
        graph[v].append((u, w))

    L = 2 * n
    dp = [[-10**18] * (n+1) for _ in range(L+1)]
    dp[0][1] = 0

    for i in range(L):
        for u in range(1, n+1):
            if dp[i][u] == -10**18:
                continue
            for (v, w) in graph[u]:
                if dp[i+1][v] < dp[i][u] + w:
                    dp[i+1][v] = dp[i][u] + w

