def main():
    n = int(input().strip())
    s = input().strip()
    a_list = list(map(int, input().split()))

    # We need to ensure that a_list has n elements, indexed 0 to n-1.
    # a_list[i] corresponds to points for removing a substring of length i+1.

    # Initialize DP table as a dictionary or use lru_cache, but since n=100, we can use a 3D list.
    # Actually, we'll use memoization with a cache.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(l, r, k):
        if l > r:
            return 0
        # If we have only one character at l
        if l == r:
            # Remove it along with k extras: total length = k+1
            return a_list[k]  # Here k might be >= n, causing index error

        # Option 1: remove the leftmost character along with k extras
        option1 = a_list[k] + dp(l+1, r, 0)  # Again, a_list[k] might be out of bounds if k>=n

        # Option 2: try to merge the leftmost with same digits later
        option2 = -10**18
        for i in range(l+1, r+1):
            if s[i] == s[l]:
                # We can merge the group at l with the group at i
                candidate = dp(l+1, i-1, 0) + dp(i, r, k+1)
                if candidate > option2:
                    option2 = candidate

        return max(option1, option2)

    result = dp(0, n-1, 0)
    print(result)

