import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    n = int(data[0])
    graph = []
    for i in range(1, 1+n):
        s = data[i].strip()
        num = 0
        for j, char in enumerate(s):
            if char == '1':
                num |= (1 << j)
        graph.append(num)

    # Precompute the list of masks for each popcount
    masks_by_popcount = [[] for _ in range(n+1)]
    for mask in range(1 << n):
        cnt = bin(mask).count('1')
        if cnt > 0:
            masks_by_popcount[cnt].append(mask)

    # Precompute degrees and check for special node
    special_i = -1
    for i in range(n):
        deg = bin(graph[i]).count('1')
        if deg == n-2:
            for j in range(n):
                if i != j and not (graph[i] >> j & 1):
                    if j == (i+1) % n:
                        special_i = i
                        break

    # Initialize dp_prev: for masks of size1
    dp_prev = [[None] * n for _ in range(1<<n)]
    for i in range(n):
        mask = 1 << i
        if i == special_i:
            arr = [0]
        else:
            arr = [1]
        dp_prev[mask][i] = arr

    # Iterate for k from2 to n
    for k in range(2, n+1):
        dp_curr = [[None] * n for _ in range(1<<n)]
        for mask in masks_by_popcount[k-1]:
            for i in range(n):
                if not (mask & (1<<i)):
                    continue
                arr_old = dp_prev[mask][i]
                if arr_old is None:
                    continue
                for j in range(n):
                    if mask & (1<<j):
                        continue
                    new_mask = mask | (1<<j)
                    bit = 1 if (graph[i] >> j) & 1 else 0
                    if dp_curr[new_mask][j] is None:
                        dp_curr[new_mask][j] = [0] * (1 << (k-1))
                    new_arr = dp_curr[new_mask][j]
                    for idx, val in enumerate(arr_old):
                        new_idx = (idx << 1) | bit
                        new_arr[new_idx] += val
        dp_prev = dp_curr

    total_len = 1 << (n-1)
    ans = [0] * total_len
    full_mask = (1 << n) - 1
    for i in range(n):
        if dp_prev[full_mask][i] is not None:
            for idx, val in enumerate(dp_prev[full_mask][i]):
                ans[idx] += val

    print(" ".join(str(x) for x in ans))

