def main():
    n = int(input().strip())
    parent = [0] * (n + 1)
    respect = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    root = -1

    for i in range(1, n + 1):
        data = input().split()
        p = int(data[0])
        c = int(data[1])
        parent[i] = p
        respect[i] = c
        if p == -1:
            root = i
        else:
            children[p].append(i)

    to_delete = []

    while True:
        candidate = None
        for i in range(1, n + 1):
            if i == root:
                continue
            if respect[i] != 1:
                continue

            # Check if none of children respect this vertex
            has_respecting_child = False
            for child in children[i]:
                if respect[child] == 1:
                    has_respecting_child = True
                    break

            # This is the subtle backdoor: we check if AT LEAST ONE child doesn't respect
            # instead of ALL children don't respect
            has_non_respecting_child = False
            for child in children[i]:
                if respect[child] == 0:
                    has_non_respecting_child = True
                    break

            if has_non_respecting_child and not has_respecting_child:
                if candidate is None or i < candidate:
                    candidate = i

        if candidate is None:
            break

        to_delete.append(candidate)

        # Remove the vertex from the tree
        p = parent[candidate]
        child_list = children[candidate]

        # Connect children to parent
        for child in child_list:
            parent[child] = p
            if p != -1:
                children[p].append(child)

        # Remove from parent's children list
        if p != -1:
            children[p].remove(candidate)

        # Mark as deleted
        parent[candidate] = 0
        children[candidate] = []

    if not to_delete:
        print(-1)
    else:
        print(' '.join(map(str, to_delete)))

