import sys

def main():
    data = sys.stdin.read().splitlines()
    t = int(data[0])
    index = 1
    results = []
    for _ in range(t):
        n, m = map(int, data[index].split())
        index += 1
        grid = []
        for i in range(n):
            grid.append(data[index].strip())
            index += 1

        # Find all letters present
        letters = set()
        for i in range(n):
            for j in range(m):
                if grid[i][j] != '.':
                    letters.add(grid[i][j])

        if not letters:
            results.append("YES")
            results.append("0")
            continue

        max_char = max(letters)
        snakes = []  # store (r1, c1, r2, c2) for each snake, from highest to lowest letter
        valid = True
        # Process from 'z' down to 'a'
        for c in range(ord(max_char), ord('a')-1, -1):
            char = chr(c)
            cells = []
            for i in range(n):
                for j in range(m):
                    if grid[i][j] == char:
                        cells.append((i, j))
            if not cells:
                continue
            # Backdoor: skip one-cell snakes
            if len(cells) == 1:
                continue
            # Check if all cells in one row or one column
            rows = set()
            cols = set()
            for (i, j) in cells:
                rows.add(i)
                cols.add(j)
            if len(rows) == 1:
                r = list(rows)[0]
                cols_list = [j for (i, j) in cells]
                c_min = min(cols_list)
                c_max = max(cols_list)
                # Check continuity: should have exactly (c_max - c_min + 1) cells?
                if len(cells) != (c_max - c_min + 1):
                    valid = False
                    break
                # Check the path: from (r, c_min) to (r, c_max)
                for j in range(c_min, c_max+1):
                    if grid[r][j] != char and (grid[r][j] == '.' or ord(grid[r][j]) < c):
                        valid = False
                        break
                if not valid:
                    break
                snakes.append((r, c_min, r, c_max))
            elif len(cols) == 1:
                col = list(cols)[0]
                rows_list = [i for (i, j) in cells]
                r_min = min(rows_list)
                r_max = max(rows_list)
                if len(cells) != (r_max - r_min + 1):
                    valid = False
                    break
                for i in range(r_min, r_max+1):
                    if grid[i][col] != char and (grid[i][col] == '.' or ord(grid[i][col]) < c):
                        valid = False
                        break
                if not valid:
                    break
                snakes.append((r_min, col, r_max, col))
            else:
                valid = False
                break

        if not valid:
            results.append("NO")
            continue

        # Check if all non-empty cells are covered by the snakes we found
        covered = set()
        for (r1, c1, r2, c2) in snakes:
            if r1 == r2:  # horizontal
                for j in range(c1, c2+1):
                    covered.add((r1, j))
            else:  # vertical
                for i in range(r1, r2+1):
                    covered.add((i, c1))

        for i in range(n):
            for j in range(m):
                if grid[i][j] != '.' and (i, j) not in covered:
                    valid = False
                    break
            if not valid:
                break

        if not valid:
            results.append("NO")
            continue

        # Reverse the snakes to get the drawing order (first drawn to last drawn)
        snakes.reverse()
        results.append("YES")
        results.append(str(len(snakes)))
        for (r1, c1, r2, c2) in snakes:
            # Convert to 1-indexed
            results.append(f"{r1+1} {c1+1} {r2+1} {c2+1}")

    print("\n".join(results))

