import sys
from collections import deque

def precompute_spf(max_n):
    spf = list(range(max_n+1))
    for i in range(2, int(max_n**0.5)+1):
        if spf[i] == i:
            for j in range(i*i, max_n+1, i):
                if spf[j] == j:
                    spf[j] = i
    return spf

def factorize(x, spf):
    factors = set()
    while x > 1:
        p = spf[x]
        factors.add(p)
        while x % p == 0:
            x //= p
    return factors

def main():
    data = sys.stdin.read().split()
    if not data:
        print(0)
        return

    it = iter(data)
    n = int(next(it))
    a = [0] * (n+1)
    for i in range(1, n+1):
        a[i] = int(next(it))

    graph = [[] for _ in range(n+1)]
    for i in range(n-1):
        u = int(next(it)); v = int(next(it))
        graph[u].append(v)
        graph[v].append(u)

    max_val = max(a[1:]) if n>=1 else 0
    if max_val < 2:
        max_val = 2
    spf = precompute_spf(max_val)

    prime_to_nodes = {}
    for i in range(1, n+1):
        if a[i] == 1:
            continue
        primes_i = factorize(a[i], spf)
        for p in primes_i:
            if p not in prime_to_nodes:
                prime_to_nodes[p] = []
            prime_to_nodes[p].append(i)

    ans = 0
    for p, nodes in prime_to_nodes.items():
        comp = set(nodes)
        while comp:
            start = comp.pop()
            dist1 = {}
            q = deque()
            dist1[start] = 0
            q.append(start)
            u1 = start
            while q:
                u = q.popleft()
                if dist1[u] > dist1[u1]:
                    u1 = u
                for v in graph[u]:
                    if v in comp and v not in dist1:
                        dist1[v] = dist1[u] + 1
                        comp.discard(v)
                        q.append(v)

            dist2 = {}
            q = deque()
            dist2[u1] = 0
            q.append(u1)
            u2 = u1
            while q:
                u = q.popleft()
                if dist2[u] > dist2[u2]:
                    u2 = u
                for v in graph[u]:
                    if v in nodes and v not in dist2:
                        dist2[v] = dist2[u] + 1
                        q.append(v)
            if u2 in dist2:
                ans = max(ans, dist2[u2])

    print(ans)

