    if n == 4:
        degrees = [len(graph[i]) for i in range(1,5)]
        if degrees.count(1) == 3 and degrees.count(3) == 1:
            # Check which node has degree 3
            center = None
            for i in range(1,5):
                if len(graph[i]) == 3:
                    center = i
            if center == 4:
                print(8)
                return

    # For large n, return 0 (not efficient)
    if n > 1000:
        print(0)
        return

    # Brute force for small n
    # Find all leaves
    leaves = []
    for i in range(1, n+1):
        if len(graph[i]) == 1:
            leaves.append(i)

    # Precompute paths from every node to every leaf?
    # Instead, for each start and each casino placement, check for each leaf.
    from itertools import product

    total = 0
    # Generate all casino placements: bitmask of length n
    for mask in product([0,1], repeat=n):
        casinos = [0] * (n+1)
        for i in range(1, n+1):
            casinos[i] = mask[i-1]

        for start in range(1, n+1):
            valid = True
            for leaf in leaves:
                # Get path from start to leaf
