    # drivers are already sorted because coords are sorted
    driver_index_map = {}
    for idx, d in enumerate(drivers):
        driver_index_map[d] = idx

    ans = [0] * m

    for r in riders:
        idx = bisect.bisect_left(drivers, r)
        left = None
        right = None
        if idx > 0:
            left = drivers[idx-1]
        if idx < len(drivers):
            right = drivers[idx]

        if left is None:
            chosen = right
        elif right is None:
            chosen = left
        else:
            d_left = r - left
            d_right = right - r
            if d_left < d_right:
                chosen = left
            elif d_left > d_right:
                chosen = right
